 o.append('<path d="M100 820V80M100 820H1140" fill="none" stroke="#253f43" stroke-width="2" marker-end="url(#arrow)"/><line x1="508" y1="100" x2="508" y2="820" stroke="#68817a" stroke-dasharray="6 6"/><line x1="100" y1="460" x2="1120" y2="460" stroke="#68817a" stroke-dasharray="6 6"/><text x="110" y="45" font-size="23" font-weight="700" fill="#233e3a">↑ 高精度GPSモードの公称稼働時間が長い</text><text x="610" y="907" text-anchor="middle" font-size="23" font-weight="700" fill="#233e3a">← 軽い　バンド込み重量（g）　重い →</text><text x="610" y="940" text-anchor="middle" font-size="17" fill="#53645f">各社公表値／共通条件での実測比較ではありません</text>')
 for d in D:
  x=100+(d['weight']-30)*20.4;y=820-12*d['hours'];cx=d['cx'];cy=d['cy']
